(667339, 70187, 1368, '<td valign="top">Hey cool stuff man! I think the lightning could be worked on a little better, or the contrast, good job though :)</td>', 'Hey cool stuff man! I think the lightning could be worked on a little better, or the contrast, good job though :)', '2004-04-14 09:13:28.000000', NULL, 1),
(667341, 69324, 20027, '<td valign="top">well taken, the material also adds to the theme.</td>', 'well taken, the material also adds to the theme.', '2004-04-14 09:15:03.000000', NULL, 1),
