(667760, 70063, 15642, '<td valign="top">Please kill me now...</td>', 'Please kill me now...', '2004-04-14 13:05:22.000000', NULL, 1),
(667761, 69549, 327, '<td valign="top">Meets the challenge. I like the black and white tones for this shot. Industrial.  I would of liked the focus to include more of the wrench and a tighter crop on the right. Not a bad shot and right on for the challenge. Good luck.</td>', 'Meets the challenge. I like the black and white tones for this shot. Industrial.  I would of liked the focus to include more of the wrench and a tighter crop on the right. Not a bad shot and right on for the challenge. Good luck.', '2004-04-14 13:05:36.000000', NULL, 1),
(667762, 69148, 16648, '<td valign="top">over processed.</td>', 'over processed.', '2004-04-14 13:05:47.000000', NULL, 1),
