(667764, 69853, 19608, '<td valign="top">My favorite in the entire submission.  The black background is perfect.  Shutter speed right on with just the right amount of motion.  The facial expression of the kicker shows real determination.  (10)</td>', 'My favorite in the entire submission.  The black background is perfect.  Shutter speed right on with just the right amount of motion.  The facial expression of the kicker shows real determination.  (10)', '2004-04-14 13:06:25.000000', NULL, 1),
(667766, 69957, 15642, '<td valign="top">Beautiful, but strength or power is not here for me.</td>', 'Beautiful, but strength or power is not here for me.', '2004-04-14 13:06:49.000000', NULL, 1),
