INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(667788, 69998, 327, '<td valign="top">I see the flag reflection. Too bad that wasn''t stronger. I think it would of been had your light been a bit better. The light and the soft focus are the weakest parts of this shot to me. Not a bad entry, and it really says ''strong''!! Good luck in the challenge.</td>', 'I see the flag reflection. Too bad that wasn''t stronger. I think it would of been had your light been a bit better. The light and the soft focus are the weakest parts of this shot to me. Not a bad entry, and it really says ''strong''!! Good luck in the challenge.', '2004-04-14 13:12:42.000000', NULL, 1),
(667789, 70155, 15642, '<td valign="top">Too literal for me.</td>', 'Too literal for me.', '2004-04-14 13:12:57.000000', NULL, 1),
(667790, 69231, 19608, '<td valign="top">Extremely nice portrait.  Great composition.  I gave it a very high 9 - but it definitely would be a 10 with the following minor changes:  1)  The hands are just a tiny bit hot on the left-pointing fingers (lost some detail.) 2) The rosary is slightly soft - maybe stop down a bit.  3) A catchlight in the models eye woud help a bit.  Well done!.(9)</td>', 'Extremely nice portrait.  Great composition.  I gave it a very high 9 - but it definitely would be a 10 with the following minor changes:  1)  The hands are just a tiny bit hot on the left-pointing fingers (lost some detail.) 2) The rosary is slightly soft - maybe stop down a bit.  3) A catchlight in the models eye woud help a bit.  Well done!.(9)', '2004-04-14 13:13:30.000000', NULL, 1),
(667791, 70061, 20027, '<td valign="top">You had an excellent idea here. The execution needs to improve in focus and composition</td>', 'You had an excellent idea here. The execution needs to improve in focus and composition', '2004-04-14 13:13:31.000000', NULL, 1),
(667792, 69466, 327, '<td valign="top">Good, good composition, light and color. The focus is just a bit soft. Looks like a shot from the Discovery Channel. Nice one. Good luck in the challenge.</td>', 'Good, good composition, light and color. The focus is just a bit soft. Looks like a shot from the Discovery Channel. Nice one. Good luck in the challenge.', '2004-04-14 13:13:31.000000', NULL, 1),
(667793, 69783, 16777, '<td valign="top">Slightly out of focus</td>', 'Slightly out of focus', '2004-04-14 13:13:34.000000', NULL, 1),
(667794, 70120, 15642, '<td valign="top">Nice. I wish the foreground wasn''t in shadow.</td>', 'Nice. I wish the foreground wasn''t in shadow.', '2004-04-14 13:14:04.000000', NULL, 1),
(667795, 69727, 15642, '<td valign="top">A little flat for me.</td>', 'A little flat for me.', '2004-04-14 13:14:40.000000', NULL, 1),
