(668536, 69162, 18080, '<td valign="top">oh my god<br/>Is this staged?</td>', 'oh my godIs this staged?', '2004-04-14 18:44:08.000000', NULL, 1),
(668540, 68996, 18868, '<td valign="top">really smart composition, technically nice, really effective color palate.  I wouldn''t change a thing.  I hope you do well!</td>', 'really smart composition, technically nice, really effective color palate.  I wouldn''t change a thing.  I hope you do well!', '2004-04-14 18:45:45.000000', NULL, 1),
(668542, 70172, 18080, '<td valign="top">6 left to vote on and this is my first 10<br/>Well done. The lines are so crisp and clean. I like this a lot.</td>', '6 left to vote on and this is my first 10Well done. The lines are so crisp and clean. I like this a lot.', '2004-04-14 18:46:28.000000', NULL, 1),
(668545, 70123, 20135, '<td valign="top">Powerful image with effective composition. A pity about some the unwanted dusk marks, yet had to be in with the constraints of the competition rules I guess.</td>', 'Powerful image with effective composition. A pity about some the unwanted dusk marks, yet had to be in with the constraints of the competition rules I guess.', '2004-04-14 18:46:45.000000', NULL, 1),
(668548, 70168, 16488, '<td valign="top">Sensual.  Lovely lighting, color, mood.  Think the cropping is slightly too tight.</td>', 'Sensual.  Lovely lighting, color, mood.  Think the cropping is slightly too tight.', '2004-04-14 18:48:44.000000', NULL, 1),
(668552, 69654, 18868, '<td valign="top">Really excellent on all fronts -- capturing a symbol of monetary power in an understandable manner is a challenge of it''s own.</td>', 'Really excellent on all fronts -- capturing a symbol of monetary power in an understandable manner is a challenge of it''s own.', '2004-04-14 18:49:59.000000', NULL, 1),
