(670592, 69852, 6130, '<td valign="top">fantasic</td>', 'fantasic', '2004-04-15 17:24:42.000000', NULL, 1),
(670593, 69728, 5728, '<td valign="top">Long title! But funny :) The photo is good! Very good!</td>', 'Long title! But funny :) The photo is good! Very good!', '2004-04-15 17:24:49.000000', NULL, 1),
(670594, 70123, 6130, '<td valign="top">Great 10</td>', 'Great 10', '2004-04-15 17:25:04.000000', NULL, 1),
