(670596, 69738, 6130, '<td valign="top">Nice girl and pic.</td>', 'Nice girl and pic.', '2004-04-15 17:26:03.000000', NULL, 1),
(670603, 70197, 889, '<td valign="top">Great Unique Concept.  It would have been harder and better if you had done the egg end on since that is where it is the strongest, but it is still a great shot  and it reaceived one of my highest grades for the contest.</td>', 'Great Unique Concept.  It would have been harder and better if you had done the egg end on since that is where it is the strongest, but it is still a great shot  and it reaceived one of my highest grades for the contest.', '2004-04-15 17:34:40.000000', NULL, 1),
