(673272, 69915, 18191, '<td valign="top">The shot looks a little bit pixelated, but nice concept and good shot anyways.</td>', 'The shot looks a little bit pixelated, but nice concept and good shot anyways.', '2004-04-17 21:32:06.000000', NULL, 1),
(673273, 69422, 18191, '<td valign="top">Very pretty and great focus.</td>', 'Very pretty and great focus.', '2004-04-17 21:32:59.000000', NULL, 1),
