(674826, 70052, 18552, '<td valign="top">Great picture for the challenge. A bunch of ahpids like this really can be strong - they destroyed my delphiniums last year. The blurred background really adds emphasis to the subject.</td>', 'Great picture for the challenge. A bunch of ahpids like this really can be strong - they destroyed my delphiniums last year. The blurred background really adds emphasis to the subject.', '2004-04-19 03:24:19.000000', NULL, 1),
(674827, 69162, 18852, '<td valign="top">that is intense</td>', 'that is intense', '2004-04-19 03:24:32.000000', NULL, 1),
(674829, 69787, 18552, '<td valign="top">Great picture. Your little boy really has the spiderman pose perfect! The color and focus of your picture is really excellent.</td>', 'Great picture. Your little boy really has the spiderman pose perfect! The color and focus of your picture is really excellent.', '2004-04-19 03:25:29.000000', NULL, 1),
(674831, 69952, 18552, '<td valign="top">Excellent picture. I like the color and focus and the black background.</td>', 'Excellent picture. I like the color and focus and the black background.', '2004-04-19 03:26:54.000000', NULL, 1),
(674833, 69116, 18852, '<td valign="top">wow!  i love the wings.</td>', 'wow!  i love the wings.', '2004-04-19 03:27:11.000000', NULL, 1),
(674836, 69336, 18852, '<td valign="top">focus on something, and focus sharp.</td>', 'focus on something, and focus sharp.', '2004-04-19 03:28:12.000000', NULL, 1),
